CREATE OR REPLACE PROCEDURE sp(arg1 real, arg2 text, arg3 real, arg4 text)
LANGUAGE plpgsql
AS $$
DECLARE
    result_val real;
    status_text text;
BEGIN
    IF arg1 < 0 THEN
        result_val := arg1 * -1;
        UPDATE chip_model
           SET ram_mib = result_val
         WHERE wifi = arg2;
    ELSIF arg1 < 10 THEN
        result_val := arg1 + 5;
        DELETE FROM chip_model
         WHERE ram_mib = arg1;
    ELSIF arg1 < 20 THEN
        result_val := arg1 * 2;
        UPDATE screen_mode
           SET used_kb = arg3 + result_val
         WHERE pixels = arg4;
    ELSIF arg1 < 30 THEN
        result_val := arg1 - 8;
        DELETE FROM screen_mode
         WHERE used_kb = arg3;
    ELSE
        result_val := arg1 / 2;
        status_text := 'processed';
    END IF;

    UPDATE phone p
       SET accreditation_level = p.accreditation_level || '_screen_match'
     WHERE EXISTS (
           SELECT 1
             FROM screen_mode sm
            WHERE sm.pixels = arg4
              AND sm.used_kb = arg3
              AND p.screen_mode = sm.graphics_mode::text
       );

    UPDATE phone p
       SET accreditation_type = p.accreditation_type || '_wifi_match'
     WHERE EXISTS (
           SELECT 1
             FROM chip_model cm
            WHERE cm.wifi = arg2
              AND p.chip_model = cm.model_name
       );

    UPDATE phone p
       SET hardware_model_name = p.hardware_model_name || '_ram_wifi_match'
     WHERE EXISTS (
           SELECT 1
             FROM chip_model cm
            WHERE cm.ram_mib = arg1
              AND cm.wifi = arg2
              AND p.chip_model = cm.model_name
       );

    UPDATE phone p
       SET accreditation_type = p.accreditation_type || '_dual_match'
     WHERE EXISTS (
           SELECT 1
             FROM chip_model cm
            WHERE cm.wifi = arg2
              AND p.chip_model = cm.model_name
       )
       AND EXISTS (
           SELECT 1
             FROM screen_mode sm
            WHERE sm.pixels = arg4
              AND p.screen_mode = sm.graphics_mode::text
       );

    UPDATE chip_model
       SET wifi = arg2 || status_text
     WHERE ram_mib = arg1;

    result_val := result_val + 3;

    UPDATE screen_mode
       SET pixels = arg4 || '_updated'
     WHERE used_kb = arg3;

    DELETE FROM chip_model
     WHERE ram_mib > result_val;

    status_text := 'active';

    UPDATE screen_mode
       SET used_kb = arg3 + 12
     WHERE pixels = arg4;

    UPDATE chip_model
       SET ram_mib = result_val
     WHERE wifi = arg2;

    result_val := result_val - 7;

    DELETE FROM screen_mode
     WHERE pixels = arg4 || '_old';

    UPDATE chip_model
       SET wifi = arg2 || '_final'
     WHERE ram_mib = arg1;

    status_text := 'completed';

    UPDATE screen_mode
       SET used_kb = arg3 * 3
     WHERE pixels = arg4;

    DELETE FROM chip_model
     WHERE wifi = arg2 || status_text;
END;
$$;

